def is_one():
    try:
        with open('/proc/stb/info/model') as f:
            return f.read().strip() in ('one', 'dreamone', 'dreamboxone')
    except Exception:
        return False


def active():
    try:
        with open(PIDFILE) as f:
            pid = int(f.read().strip())
        os.kill(pid, 0)
        return True
    except Exception:
        return False


def current_mode():
    try:
        with open(MODEFILE) as f:
            return f.read().strip() or 'install'
    except Exception:
        return 'install'


def receiver_size():
    try:
        sz = getDesktop(0).size()
        w, h = sz.width(), sz.height()
        if 800 <= w <= 4096 and 480 <= h <= 2160:
            return w, h
    except Exception:
        pass
    return 1280, 720


def geometry():
    w, h = receiver_size()
    f = min(float(w) / 1280.0, float(h) / 720.0)
    return w, h, f, int((w - 1280 * f) / 2), int((h - 720 * f) / 2)


def coords(x, y, f, ox, oy):
    return ox + int(round(x * f)), oy + int(round(y * f))


def box(name, x, y, w, h, f, ox, oy, **kw):
    xx, yy = coords(x, y, f, ox, oy)
    # All widgets must paint ABOVE the full-screen static background ePixmap.
    # Default z=0 is theme-dependent and previously caused an empty-screen view.
    if 'zPosition' not in kw:
        kw['zPosition'] = '3'
    args = ' '.join('%s="%s"' % (k, v) for k, v in kw.items())
    return '<widget name="%s" position="%d,%d" size="%d,%d" %s />' % (
        name, xx, yy, int(round(w * f)), int(round(h * f)), args)


def bgname(w):
    return ASSETS + ('/background_1920.png' if w >= 1600 else '/background_1280.png')


# Compact 720p-first layout: all 20 plugins fit without a long vertical list.
# Sections are labels, not selectable tabs. Visual order is independent of install order.
LEFT_X, RIGHT_X = 24, 655
CARD_W, CARD_H = 142, 69
GAP_X, GAP_Y, HEADING_H, GROUP_SPACE = 7, 5, 24, 9
VIEW_TOP, VIEW_BOTTOM = 93, 641
VIEW_HEIGHT = VIEW_BOTTOM - VIEW_TOP
LEFT_GROUPS = ('Panels', 'Audio', 'Media', 'Other Plugins')


def sections_layout():
    cards, headers = [], []
    ys = {0: 0, 1: 0}
    for label, keys in GROUPS:
        column = 0 if label in LEFT_GROUPS else 1
        x0 = LEFT_X if column == 0 else RIGHT_X
        y = ys[column]
        headers.append((label, x0, y))
        y += HEADING_H
        for i, key in enumerate(keys):
            col, row = i % 4, i // 4
            cards.append({'key': key,
                          'x': x0 + col * (CARD_W + GAP_X),
                          'y': y + row * (CARD_H + GAP_Y),
                          'row': row})
        rows = (len(keys) + 3) // 4
        ys[column] = y + rows * CARD_H + max(0, rows - 1) * GAP_Y + GROUP_SPACE
    return cards, headers, max(ys.values())


CARDS, HEADERS, VIRTUAL_HEIGHT = sections_layout()


